{
  "findings": [
    {
      "check_id": "CKV_AZURE_53",
      "title": "Ensure 'public network access enabled' is set to 'False' for mySQL servers",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The MySQL server is not configured to disable public network access, potentially exposing it to unauthorized access."
    },
    {
      "check_id": "CKV_AZURE_54",
      "title": "Ensure MySQL is using the latest version of TLS encryption",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The MySQL server is not explicitly configured to use the latest TLS version, which may lead to using an outdated and potentially vulnerable TLS version."
    },
    {
      "check_id": "CKV_AZURE_94",
      "title": "Ensure that My SQL server enables geo-redundant backups",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The MySQL server does not have geo-redundant backups enabled, which may result in data loss in case of a regional outage."
    },
    {
      "check_id": "CKV_AZURE_127",
      "title": "Ensure that My SQL server enables Threat detection policy",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The MySQL server does not have a Threat detection policy enabled, potentially missing security threats."
    },
    {
      "check_id": "CKV2_AZURE_16",
      "title": "Ensure that MySQL server enables customer-managed key for encryption",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The MySQL server does not use a customer-managed key for encryption, relying on Microsoft-managed keys instead."
    }
  ],
  "patched_code": "resource \"azurerm_mysql_server\" \"changeme_simple_mysql_server\" {\n  name                = \"changeme-simple-mysql-database-name\"\n  resource_group_name = azurerm_resource_group.changeme_simple_mysql_server_resource_group.name\n  location            = azurerm_resource_group.changeme_simple_mysql_server_resource_group.location\n  storage_mb = \"5120\"\n  sku_name   = \"B_Gen5_1\"\n  version    = \"8.0\"\n  administrator_login          = \"changemeadmin\"\n  administrator_login_password = \"ch4ng3m3-A@\\u00A2\\u00A3$%^&\"\n  ssl_enforcement_enabled = true\n  public_network_access_enabled = false\n  storage_account_geo_redundant_enabled = true\n  threat_detection_policy {\n    enabled = true\n  }\n}\nresource \"azurerm_mysql_server_key\" \"changeme_simple_mysql_server_key\" {\n  server_id        = azurerm_mysql_server.changeme_simple_mysql_server.id\n  key_vault_key_id = \"insert_key_vault_key_id_here\"\n}\nresource \"azurerm_mysql_configuration\" \"changeme_simple_mysql_server_tls_version\" {\n  name                = \"tls_version\"\n  resource_group_name = azurerm_resource_group.changeme_simple_mysql_server_resource_group.name\n  server_name         = azurerm_mysql_server.changeme_simple_mysql_server.name\n  value               = \"TLS1_2\"\n}",
  "fix_summary": "Added 'public_network_access_enabled = false' to disable public access, 'storage_account_geo_redundant_enabled = true' for geo-redundant backups, a 'threat_detection_policy' block to enable threat detection, created a 'azurerm_mysql_server_key' resource to enable customer-managed keys, and added a 'azurerm_mysql_configuration' resource to enforce TLS 1.2."
}
